// MT2009_PLUS_AUTOHUNT_TEST_V1 (command) (server-patches/autohunttest, the owner, 28 October 2026): the TEST auto hunt of root's
// uiautohunt_test.py (Alt+H). The client exe hunts by itself (the normal attack, skill and item packets); the server only
// says whether it may: "/autohunt_test b" (the start, then once a minute while it runs) -> "AutoHuntTest on", or
// "AutoHuntTest off flag" with the event flag autohunt_test_off ("/e autohunt_test_off 1" switches it off for everybody),
// "AutoHuntTest off item" with the event flag autohunt_test_ticket and no Auto Lowy ticket (the 8 h affect 560 or the
// 7 / 14 day items 72800 / 72801, as for Auto Lowy). "/autohunt_test d": stopped (log only). A character without a
// connection (a bot) gets nothing.
ACMD(do_autohunt_test)
{
	if (!ch || !ch->GetDesc())
		return;
	char arg1[256];
	one_argument(argument, arg1, sizeof(arg1));
	if (arg1[0] != 'b')
	{
		sys_log(1, "AUTOHUNT_TEST: %s stop", ch->GetName());
		return;
	}
	if (quest::CQuestManager::instance().GetEventFlag("autohunt_test_off"))
	{
		ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoHuntTest off flag");
		return;
	}
	if (quest::CQuestManager::instance().GetEventFlag("autohunt_test_ticket"))
	{
		if (!ch->IsLoadedAffect())
			return;
		if (!ch->FindAffect(560) && ch->CountSpecifyItem(72800) + ch->CountSpecifyItem(72801) <= 0)
		{
			ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoHuntTest off item");
			return;
		}
	}
	sys_log(1, "AUTOHUNT_TEST: %s start", ch->GetName());
	ch->ChatPacket(CHAT_TYPE_COMMAND, "AutoHuntTest on");
}
